import {
  Object3D,
  PlaneGeometry,
  Mesh,
  NodeMaterial,
  TextureLoader,
  Color,
  Euler,
  Vector3
} from 'three/webgpu';
import {
  texture,
  uv,
  displacementMap,
  vec3,
  mul,
  float
} from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // --- load textures ---
  const mapTexture = ctx.textureLoader.load(config.assets.imageUrl);
  const depthTexture = ctx.textureLoader.load(config.assets.depthMapUrl);

  // --- geometry ---
  const aspect = 512 / 320; // from source rect
  const geo = new PlaneGeometry(aspect, 1, 64, 64);

  // --- displacement node (TSL) ---
  const depthNode = texture(depthTexture, uv());
  // map depth (0‐1) to displacement offset (e.g., scale 0.05)
  const displacementScale = float(0.05);
  const displacementNode = mul(depthNode, displacementScale);

  // --- material (NodeMaterial with physical features) ---
  const material = new NodeMaterial();
  material.map = mapTexture;
  material.displacementNode = displacementNode;
  material.roughness = 0.6;
  material.metalness = 0.5;
  material.clearcoat = 0.25;
  material.clearcoatRoughness = 0.3;
  material.envMapIntensity = 1.0;

  // --- mesh ---
  const mesh = new Mesh(geo, material);
  mesh.position.set(
    config.scenePlacement.position[0],
    config.scenePlacement.position[1],
    config.scenePlacement.position[2]
  );
  mesh.rotation.set(
    config.scenePlacement.rotation[0],
    config.scenePlacement.rotation[1],
    config.scenePlacement.rotation[2]
  );
  mesh.scale.set(
    config.scenePlacement.scale[0],
    config.scenePlacement.scale[1],
    config.scenePlacement.scale[2]
  );

  // store original position for hover reset
  const origY = mesh.position.y;

  // --- weighted‑settle entrance (GSAP) ---
  const entranceTimeline = gsap.timeline({ paused: false });
  entranceTimeline.fromTo(
    mesh.scale,
    { x: 0, y: 0, z: 0 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out', overwrite: 'auto' }
  );

  // --- event handlers (hover, click) ---
  const handlers = {};

  handlers.pointerenter = () => {
    gsap.to(mesh.position, {
      y: origY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
      overwrite: 'auto'
    });
  };

  handlers.pointerleave = () => {
    gsap.to(mesh.position, {
      y: origY,
      duration: 0.7,
      ease: 'power3.out',
      overwrite: 'auto'
    });
  };

  handlers.click = () => {
    mesh.dispatchEvent({ type: 'hub-pricing.select' });
  };

  mesh.userData.handlers = handlers;

  // --- apply cinematic primitives ---
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](mesh, primitive.params);
      }
    });
  }

  // --- cleanup ---
  mesh.userData.cleanup = () => {
    entranceTimeline.kill();
    geometry.dispose();
    material.dispose();
    mapTexture.dispose();
    depthTexture.dispose();
    // Remove any primitives cleanup if necessary
  };

  return mesh;
}
